import re

def primary_language(desc):
    if not isinstance(desc, str):
        return None
    # find all (lang, bytes) pairs
    matches = re.findall(r'([A-Za-z+#\-\. ]+?)\s*\(([\d,]+)\s*bytes\)', desc)
    if not matches:
        return None
    best = max(matches, key=lambda x: int(x[1].replace(',', '')))
    return best[0].strip()

